function validarCorreo(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)}function solo_letras(t){return/^[A-Za-zÁÉÍÓÚáéíóúÑñ\s]+$/.test(t)}function validarLongitud(t,e){return t.toString().length===Number(e)}function calcularEdad(t){let e=new Date(t),n=new Date,r=n.getFullYear()-e.getFullYear(),a=n.getMonth()-e.getMonth();return(a<0||0===a&&n.getDate()<e.getDate())&&r--,r}function esMayorEdad(t){return calcularEdad(t)>=18}function validarPassword(t){return/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&.#_-])[A-Za-z\d@$!%*?&.#_-]{8,}$/.test(t)}function validarCodigoPostal(t){}function contarCaracteres(t){return t.length}function contieneTexto(t,e){return t.toLowerCase().includes(e.toLowerCase())}function solo_numeros(t){return/^\d+$/.test(Number(t))}function validarTelefono(t){let e=t.toString();return"55"===e.substring(0,2)?e+"es de: Ciudad de México (CDMX)":"442"===e.substring(0,3)||"446"===e.substring(0,3)?e+"es de: Querétaro":"951"===e.substring(0,3)?e+"es de: Oaxaca":"No se identifica la LADA del número"}